from pathlib import Path
import pandas as pd, json, html
O=Path('outputs')
bat=pd.read_csv(O/'batter_leaderboard.csv').to_dict(orient='records')
bowl=pd.read_csv(O/'bowler_leaderboard.csv').to_dict(orient='records')
data=json.dumps({'batters':bat,'bowlers':bowl},ensure_ascii=False,separators=(',',':'))
template=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#102820"><title>Rajasthan Royals | Pressure Performance</title>
<style>
:root{--ink:#17243a;--muted:#667085;--line:#efdee8;--paper:#fbf6fa;--white:#fff;--forest:#071e3d;--forest2:#e5007d;--lime:#ffc72c;--orange:#b42370;--shadow:0 14px 34px rgba(25,52,39,.08);--radius:19px}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,input{font:inherit}.shell{max-width:1420px;margin:auto;padding:26px 34px 46px}.hero{background:var(--forest);color:white;border-radius:25px;padding:29px 34px 30px;position:relative;overflow:hidden;box-shadow:var(--shadow)}.hero:after{content:"";position:absolute;width:310px;height:310px;border:1px solid rgba(216,243,106,.24);border-radius:50%;right:5%;top:-190px;box-shadow:0 0 0 25px rgba(216,243,106,.035),0 0 0 52px rgba(216,243,106,.035)}.eyebrow{font-size:11px;letter-spacing:.16em;font-weight:800;color:var(--lime);text-transform:uppercase}.hero h1{font-size:clamp(29px,4vw,48px);line-height:1.05;letter-spacing:-.045em;margin:14px 0 10px;max-width:760px}.hero p{margin:0;color:#d8deeb;font-size:14px;max-width:700px;line-height:1.6}.hero-meta{position:absolute;right:34px;bottom:30px;color:#e7eaf0;font-size:11px;letter-spacing:.04em;text-align:right}.hero-meta b{display:block;color:var(--lime);font-size:22px;margin-bottom:3px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin:17px 0 22px}.stat{padding:17px 20px;background:var(--white);border:1px solid var(--line);border-radius:16px;box-shadow:0 4px 18px rgba(20,40,30,.025)}.stat small{display:block;text-transform:uppercase;letter-spacing:.1em;font-size:10px;color:var(--muted);font-weight:800}.stat strong{display:block;margin-top:6px;font-size:25px;letter-spacing:-.04em;color:var(--forest)}.main{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(300px,.8fr);gap:18px;align-items:start}.panel{background:white;border:1px solid var(--line);border-radius:var(--radius);box-shadow:var(--shadow)}.rankings{overflow:hidden}.panel-head{display:flex;align-items:flex-start;justify-content:space-between;gap:14px;padding:23px 24px 16px}.panel-head h2{font-size:19px;letter-spacing:-.03em;margin:0}.panel-head p{color:var(--muted);font-size:12px;margin:5px 0 0;line-height:1.5}.tabs{display:flex;padding:4px;background:#f8edf3;border-radius:12px;gap:3px;flex-shrink:0}.tabs button,.view-switch button{border:0;background:transparent;border-radius:9px;padding:9px 14px;font-size:12px;font-weight:750;color:#68758a;cursor:pointer}.tabs button.active{background:var(--forest);color:#fff;box-shadow:0 3px 8px rgba(19,59,46,.18)}.toolbar{display:flex;gap:10px;padding:0 24px 16px;align-items:center}.search{position:relative;flex:1}.search input{width:100%;border:1px solid var(--line);background:#fbfcfa;border-radius:11px;padding:11px 13px 11px 37px;outline:0;color:var(--ink);font-size:12px}.search input:focus{border-color:#91af9c;box-shadow:0 0 0 3px rgba(32,76,60,.08)}.search span{position:absolute;left:13px;top:10px;color:#79859a;font-size:15px}.view-switch{display:flex;gap:2px;background:#f7f0f4;border-radius:11px;padding:3px}.view-switch button{padding:8px 10px;font-size:11px;white-space:nowrap}.view-switch button.active{background:#fff;color:var(--forest);box-shadow:0 2px 7px rgba(20,40,30,.08)}.table-wrap{overflow:auto;border-top:1px solid var(--line)}table{border-collapse:collapse;width:100%;min-width:680px}thead th{text-align:left;padding:11px 11px;color:#68758a;font-size:9px;letter-spacing:.09em;text-transform:uppercase;background:#fafbf9;white-space:nowrap}thead th:first-child,tbody td:first-child{padding-left:24px}thead th:last-child,tbody td:last-child{padding-right:24px}tbody tr{border-top:1px solid #edf1ed;cursor:pointer;transition:background .15s}tbody tr:hover{background:#fff8fb}tbody tr.selected{background:#fff1f7}td{padding:12px 11px;font-size:12px;white-space:nowrap}td.rank{color:#8490a1;font-weight:750;width:45px}.player{font-weight:760;color:#1c342a}.context{font-size:10px;color:var(--muted);margin-top:3px}.metric{font-variant-numeric:tabular-nums;font-weight:650}.delta{font-weight:800;color:#246246}.score-cell{width:116px}.score-top{display:flex;align-items:center;justify-content:space-between;gap:8px;font-weight:800;font-size:12px}.score-bar{margin-top:6px;height:5px;background:#edf1eb;border-radius:9px;overflow:hidden}.score-bar i{display:block;height:100%;background:var(--forest2);border-radius:9px}.empty{display:none;text-align:center;padding:36px;color:var(--muted);font-size:13px}.table-foot{padding:12px 24px 15px;color:#8490a1;font-size:10px;border-top:1px solid var(--line)}.side{display:grid;gap:17px}.side-panel{padding:21px 22px}.side-title{display:flex;justify-content:space-between;align-items:center}.side-title h3{font-size:15px;margin:0;letter-spacing:-.02em}.badge{font-size:9px;color:#5c2950;background:#fbeaf3;border-radius:20px;padding:6px 9px;font-weight:800;text-transform:uppercase;letter-spacing:.08em}.leader-name{font-size:24px;letter-spacing:-.04em;font-weight:800;margin:20px 0 3px;color:var(--forest)}.leader-sub{font-size:11px;color:var(--muted)}.leader-main{margin-top:17px;padding:16px;background:#fbf0f6;border-radius:14px;display:flex;align-items:end;justify-content:space-between}.leader-main strong{font-size:32px;letter-spacing:-.055em;color:var(--forest)}.leader-main span{font-size:10px;color:var(--muted);text-align:right;line-height:1.4}.compare{margin-top:16px}.compare-head{display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-bottom:7px}.compare-rail{height:9px;background:#ebefeb;border-radius:9px;position:relative;overflow:hidden}.compare-rail i{display:block;height:100%;border-radius:9px;background:var(--orange)}.rate-row{display:flex;justify-content:space-between;margin-top:12px;font-size:11px}.rate-row span{color:var(--muted)}.rate-row b{font-variant-numeric:tabular-nums}.chart-list{display:grid;gap:13px;margin-top:18px}.chart-row{display:grid;grid-template-columns:23px 1fr 46px;align-items:center;gap:8px;font-size:10px}.chart-row .n{font-weight:800;color:#8490a1}.chart-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-weight:700}.chart-track{grid-column:2 / 3;grid-row:2;height:5px;background:#edf1eb;border-radius:9px;overflow:hidden;margin-top:-3px}.chart-track i{display:block;height:100%;background:#e5007d;border-radius:9px}.chart-val{grid-column:3;grid-row:1 / span 2;text-align:right;font-weight:800;font-variant-numeric:tabular-nums}.note{padding:18px 20px;background:#fff2f8;border:1px solid #f3d8e6;border-radius:16px}.note h3{font-size:12px;margin:0 0 10px}.note p{font-size:11px;color:#58657a;line-height:1.6;margin:0}.note b{color:#254735}.footer{margin:18px 3px 0;color:#7b8799;font-size:10px;display:flex;justify-content:space-between;gap:10px}.footer a{color:#123d70;text-decoration:none;font-weight:700}.sr{position:absolute;left:-10000px}.mobile-hint{display:none}
@media(max-width:1000px){.main{grid-template-columns:1fr}.side{grid-template-columns:1fr 1fr}.note{grid-column:1/-1}.hero-meta{position:static;text-align:left;margin-top:18px}.hero-meta b{display:inline;margin-right:5px}.hero:after{right:-10%}}
@media(max-width:650px){.shell{padding:14px 12px 28px}.hero{padding:24px 21px;border-radius:20px}.hero h1{font-size:34px}.stats{gap:7px}.stat{padding:13px 11px}.stat strong{font-size:19px}.stat small{font-size:8px}.panel-head{padding:18px 16px 13px;flex-direction:column}.tabs{width:100%}.tabs button{flex:1}.toolbar{padding:0 16px 14px;flex-direction:column;align-items:stretch}.view-switch{justify-content:center}.side{grid-template-columns:1fr}.note{grid-column:auto}.table-foot{padding-left:16px}.mobile-hint{display:block}.footer{flex-direction:column}}
</style></head><body><div class="shell">
<header class="hero"><div class="eyebrow">RAJASTHAN ROYALS · SUPERR SELECTOR S2</div><h1>Who holds up<br>under pressure?</h1><p>A delivery-level view of the players who lift their performance when the match gets tight. Compare pressure output with each player's own ordinary baseline.</p><div class="hero-meta"><b>2022—2026</b>Supplied T20 and T20I data</div></header>
<section class="stats" aria-label="Dataset summary"><div class="stat"><small>Matches with usable innings</small><strong>867</strong></div><div class="stat"><small>Deliveries tagged pressure</small><strong>76,933</strong></div><div class="stat"><small>Eligible player rankings</small><strong id="eligibleCount">—</strong></div></section>
<main class="main"><section class="panel rankings" aria-labelledby="rank-title"><div class="panel-head"><div><h2 id="rank-title">Pressure rankings</h2><p id="subtitle">Batter performance against ordinary deliveries</p></div><div class="tabs" role="tablist" aria-label="Player type"><button class="active" data-kind="batters" role="tab" aria-selected="true">Batters</button><button data-kind="bowlers" role="tab" aria-selected="false">Bowlers</button></div></div>
<div class="toolbar"><label class="search"><span>⌕</span><input id="search" type="search" placeholder="Find a player" aria-label="Find a player"></label><div class="view-switch" aria-label="Number of players"><button class="active" data-view="10">Top 10</button><button data-view="all">All eligible</button></div></div>
<div class="table-wrap"><table><thead><tr><th>#</th><th>Player</th><th id="pressureCol">Pressure SR</th><th id="ordinaryCol">Usual SR</th><th>Lift</th><th>Pressure sample</th><th>Adjusted score</th></tr></thead><tbody id="rows"></tbody></table><div id="empty" class="empty">No matching players. Try a shorter search.</div></div><div class="table-foot">Select a row to inspect its baseline, pressure rate, and sample reliability. <span class="mobile-hint">Swipe sideways to see all columns.</span></div></section>
<aside class="side"><section class="panel side-panel" aria-live="polite"><div class="side-title"><h3>Player snapshot</h3><span class="badge" id="playerRank">Rank #1</span></div><div class="leader-name" id="playerName">—</div><div class="leader-sub" id="playerType">—</div><div class="leader-main"><div><strong id="playerScore">—</strong></div><span>Reliability-adjusted<br>pressure score</span></div><div class="compare"><div class="compare-head"><span id="ordinaryLabel">Ordinary baseline</span><span id="pressureLabel">Pressure</span></div><div class="compare-rail"><i id="compareBar" style="width:50%"></i></div></div><div class="rate-row"><span>Ordinary output</span><b id="ordinaryValue">—</b></div><div class="rate-row"><span>Pressure output</span><b id="pressureValue">—</b></div><div class="rate-row"><span>Pressure deliveries</span><b id="pressureBalls">—</b></div><div class="rate-row"><span>Pressure matches</span><b id="pressureMatches">—</b></div></section>
<section class="panel side-panel"><div class="side-title"><h3>Top performers</h3><span class="badge">Adjusted score</span></div><div id="chart" class="chart-list"></div></section>
<section class="note"><h3>How the model defines pressure</h3><p><b>Chase:</b> required rate ≥9, five or fewer wickets after 10 overs, or final five overs. <b>First innings:</b> final five overs with five or fewer wickets. Situation is read before each ball; revised targets and shortened allocations are used when supplied. Scores compare pressure with each player's own ordinary baseline and shrink thin samples.</p></section></aside></main>
<footer class="footer"><span>Pressure scoring is a transparent heuristic, not a win-probability model.</span><a href="pressure_performance_methodology.pdf">Read the methodology report ↗</a></footer></div>
<script>window.DASH_DATA=__DATA__;
let data=window.DASH_DATA; let kind='batters', view='10', selected=null, query='';
const $=id=>document.getElementById(id); const fmt=n=>Number(n).toLocaleString('en-US');
function players(){return data[kind]||[]} function rateLabel(){return kind==='batters'?'SR':'Economy'} function rateFmt(r){return kind==='batters'?Number(r).toFixed(1):Number(r).toFixed(2)} function lift(r){return kind==='batters'?r.pressure_rate-r.ordinary_rate:r.ordinary_rate-r.pressure_rate}
function render(){const all=players(); $('eligibleCount').textContent=all.length.toLocaleString('en-US');$('subtitle').textContent=kind==='batters'?'Batter performance against ordinary deliveries':'Bowler performance against ordinary deliveries';$('pressureCol').textContent='Pressure '+rateLabel();$('ordinaryCol').textContent='Usual '+rateLabel();
let shown=all.filter(x=>x.player.toLowerCase().includes(query.toLowerCase()));if(view==='10'&&!query)shown=shown.slice(0,10);$('rows').replaceChildren();$('empty').style.display=shown.length?'none':'block';$('rows').style.display=shown.length?'table-row-group':'none';
const max=Math.max(...all.map(x=>Number(x.adjusted_score)),1);
for(const r of shown){const tr=document.createElement('tr');tr.className=selected&&selected.player_id===r.player_id?'selected':'';tr.tabIndex=0;tr.setAttribute('aria-label',`${r.rank}. ${r.player}`);const vals=[['rank',r.rank],['player',r.player],['pressure',rateFmt(r.pressure_rate)],['ordinary',rateFmt(r.ordinary_rate)],['lift',(lift(r)>=0?'+':'')+rateFmt(lift(r))],['sample',`${fmt(r.pressure_balls)} balls · ${r.pressure_matches} matches`]];for(const [k,v] of vals){const td=document.createElement('td');td.className=k==='rank'?'rank':k==='player'?'player':k==='lift'?'delta':k==='pressure'||k==='ordinary'?'metric':'';td.textContent=v;tr.appendChild(td)}const td=document.createElement('td');td.className='score-cell';td.innerHTML=`<div class="score-top"><span>${Number(r.adjusted_score).toFixed(1)}</span></div><div class="score-bar"><i style="width:${Math.max(2,Number(r.adjusted_score)/max*100)}%"></i></div>`;tr.appendChild(td);tr.addEventListener('click',()=>select(r));tr.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(r)}});$('rows').appendChild(tr)}
if(!selected||!all.some(x=>x.player_id===selected.player_id))selected=all[0]||null;if(selected)updateSnapshot(selected);renderChart(all.slice(0,5),max)}
function select(r){selected=r;render()}
function updateSnapshot(r){$('playerRank').textContent='Rank #'+r.rank;$('playerName').textContent=r.player;$('playerType').textContent=kind==='batters'?'Batter · player ID '+r.player_id:'Bowler · player ID '+r.player_id;$('playerScore').textContent=Number(r.adjusted_score).toFixed(1);$('ordinaryLabel').textContent='Ordinary '+rateLabel();$('pressureLabel').textContent='Pressure '+rateLabel();$('ordinaryValue').textContent=rateFmt(r.ordinary_rate)+(kind==='batters'?' runs/100 balls':' runs/over');$('pressureValue').textContent=rateFmt(r.pressure_rate)+(kind==='batters'?' runs/100 balls':' runs/over');$('pressureBalls').textContent=fmt(r.pressure_balls);$('pressureMatches').textContent=fmt(r.pressure_matches);const a=Number(r.ordinary_rate),b=Number(r.pressure_rate),high=Math.max(a,b,1);$('compareBar').style.width=Math.min(100,b/high*100)+'%';$('compareBar').style.background=lift(r)>=0?'#6f9c7d':'#e87946'}
function renderChart(top,max){$('chart').replaceChildren();for(const r of top){const row=document.createElement('div');row.className='chart-row';const n=document.createElement('span');n.className='n';n.textContent=String(r.rank).padStart(2,'0');const name=document.createElement('span');name.className='chart-name';name.textContent=r.player;const val=document.createElement('span');val.className='chart-val';val.textContent=Number(r.adjusted_score).toFixed(1);const track=document.createElement('span');track.className='chart-track';const fill=document.createElement('i');fill.style.width=Math.max(3,Number(r.adjusted_score)/max*100)+'%';track.appendChild(fill);row.append(n,name,val,track);$('chart').appendChild(row)}}
document.querySelectorAll('[data-kind]').forEach(b=>b.addEventListener('click',()=>{kind=b.dataset.kind;selected=null;document.querySelectorAll('[data-kind]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});render()}));document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>{view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x===b));render()}));$('search').addEventListener('input',e=>{query=e.target.value;render()});render();
async function loadFromBackend(){if(location.protocol==='file:')return;try{const [br,wr,sr]=await Promise.all([fetch('/api/rankings?type=batters'),fetch('/api/rankings?type=bowlers'),fetch('/api/summary')]);if(!br.ok||!wr.ok||!sr.ok)throw new Error('API unavailable');data={batters:await br.json(),bowlers:await wr.json()};const summary=await sr.json();document.querySelector('.stats .stat:nth-child(1) strong').textContent=Number(summary.matches).toLocaleString('en-US');document.querySelector('.stats .stat:nth-child(2) strong').textContent=Number(summary.pressureDeliveries).toLocaleString('en-US');render()}catch(e){console.warn('Using embedded dashboard data:',e.message)}}
loadFromBackend();
</script></body></html>'''
html_doc=template.replace('__DATA__',data)
(O/'pressure_performance_dashboard.html').write_text(html_doc,encoding='utf-8')
# Prepare Render's static assets and API data files from the same current leaderboards.
app=O/'render-app'; (app/'data').mkdir(parents=True,exist_ok=True)
(app/'index.html').write_text(html_doc,encoding='utf-8')
(app/'data'/'rankings.json').write_text(data,encoding='utf-8')
summary={'matches':867,'pressureDeliveries':76933,'eligibleBatters':len(bat),'eligibleBowlers':len(bowl)}
(app/'data'/'summary.json').write_text(json.dumps(summary,separators=(',',':')),encoding='utf-8')
# Keep the repository root directly deployable on Render.
(O/'index.html').write_text(html_doc,encoding='utf-8')
(O/'data').mkdir(exist_ok=True)
(O/'data'/'rankings.json').write_text(data,encoding='utf-8')
(O/'data'/'summary.json').write_text(json.dumps(summary,separators=(',',':')),encoding='utf-8')
print('Dashboard created:', O/'pressure_performance_dashboard.html')
